# test/suites.map: which suites a changed file can break. Read by test/select.sh (and so by
# `test/all.sh --tier quick`). One rule per line:  <pattern>  <suite or @group or ALL> ...
#
# - Patterns are shell patterns matched against the path from the repository root; "*" also
#   matches "/". EVERY rule that matches a file counts: the suites are added up.
# - A changed file that no rule matches selects ALL (unknown means: run everything).
# - ALL = every suite of the full tier. Groups are defined with "@name = ...".
# - This map is a shortcut for the quick tier only. The full tier never reads it. When a suite
#   starts using another part of the tree, add the rule here; when in doubt, write ALL.

@local   = lint ui-test go install-test runner-test
@alerts  = e2e-alerts e2e-alerts-timer e2e-alerts-daemon
@faults  = e2e-faults-q1 e2e-faults-q2 e2e-faults-q3 e2e-faults-q4 e2e-faults-q5 e2e-faults-q6 e2e-matrix-quick

# ---- the core: everything depends on it
bin/*                    ALL
lib/common.sh            ALL
lib/deploy.sh            ALL
lib/build.sh             ALL
lib/native.js            ALL
lib/workspace.js         ALL
lib/args.sh              ALL
server/tando-agent       ALL
server/tando-install-recover  ALL
srv/internal/*           ALL
srv/cmd/*                ALL
srv/go.mod               ALL
srv/daemon/*             ALL
VERSION                  ALL
test/lib.sh              ALL
test/server/Dockerfile   ALL
test/server/files/*      ALL
test/server/ssh.sh       ALL
# the runner: its own check runs it with fakes, the smoke deploy runs it for real; the map is
# read only by the quick tier (the full tier, before a push, runs every suite whatever it says)
test/all.sh              runner-test lint e2e-trial
test/select.sh           runner-test lint e2e-trial
test/suites.map          runner-test lint
test/durations.tsv       runner-test lint
test/runner-test.sh      runner-test lint
test/server/up.sh        runner-test lint e2e-trial
test/server/down.sh      runner-test lint e2e-trial
test/server/README.md    lint

